// Supabase Edge Function: order-pdf
// Builds the printable purchase order for one supplier order batch and returns
// it as a real PDF (A4, Hebrew RTL). Layout lives in render.ts, the row →
// document mapping in data.ts; this file is only auth and IO.
//
// Deploy:
//   supabase functions deploy order-pdf
//
// No secrets to set: the Hebrew font is pulled from a CDN on the first request
// of an isolate and cached in memory from then on.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { PDFDocument, rgb } from "https://esm.sh/pdf-lib@1.17.1";
import fontkit from "https://esm.sh/@pdf-lib/fontkit@1.1.1";
import { loadFonts } from "./fonts.ts";
import { renderOrderPdf } from "./render.ts";
import { buildOrderPdfData, type ItemRow, type OrderRow, type SupplierPrices, type SupplierRow } from "./data.ts";

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

/** The roles that may manage orders in the app — the document carries prices. */
const MANAGER_ROLES = ["manager", "office_manager", "super_admin"];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });

  try {
    const url = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;

    const authHeader = req.headers.get("Authorization") ?? "";
    const token = authHeader.replace("Bearer ", "");
    if (!token) return json({ error: "unauthorized" }, 401);

    const userClient = createClient(url, anonKey, { global: { headers: { Authorization: authHeader } } });
    const { data: userData } = await userClient.auth.getUser(token);
    const caller = userData?.user;
    if (!caller) return json({ error: "unauthorized" }, 401);

    const body = await req.json().catch(() => ({}));
    const businessId = String(body?.business_id ?? "");
    const batchId = String(body?.batch_id ?? "");
    if (!UUID.test(businessId) || !UUID.test(batchId)) {
      return json({ error: "missing or malformed business_id / batch_id" }, 400);
    }

    const admin = createClient(url, serviceKey);

    const { data: me } = await admin
      .from("profiles")
      .select("business_id, role")
      .eq("id", caller.id)
      .maybeSingle();
    if (!me || !MANAGER_ROLES.includes(me.role)) return json({ error: "forbidden" }, 403);
    if (me.role !== "super_admin" && me.business_id !== businessId) {
      return json({ error: "forbidden" }, 403);
    }

    /* ---- the order ------------------------------------------------ */

    const { data: orderRows, error: ordersError } = await admin
      .from("inventory_orders")
      .select("id, item_id, quantity, received_quantity, status, batch_id, supplier_id, ordered_by, created_at")
      .eq("business_id", businessId)
      .or(`batch_id.eq.${batchId},id.eq.${batchId}`);
    if (ordersError) return json({ error: ordersError.message }, 500);

    // Same grouping key the app uses: a batch is `batch_id`, or the single
    // row's own id for orders created before batching existed.
    const lines = ((orderRows ?? []) as OrderRow[]).filter((row) => (row.batch_id ?? row.id) === batchId);
    if (lines.length === 0) return json({ error: "ההזמנה לא נמצאה" }, 404);

    const supplierId = lines.find((l) => l.supplier_id)?.supplier_id ?? null;
    const itemIds = [...new Set(lines.map((l) => l.item_id))];

    const [itemsRes, categoriesRes, supplierRes, pricesRes, businessRes, ordererRes] = await Promise.all([
      admin
        .from("inventory_items")
        .select("id, name, unit, units_per_package, piece_unit, barcode, category_id")
        .in("id", itemIds),
      admin.from("inventory_categories").select("id, name").eq("business_id", businessId),
      supplierId
        ? admin
            .from("suppliers")
            .select("name, phone, tax_id, notes, delivery_days")
            .eq("id", supplierId)
            .maybeSingle()
        : Promise.resolve({ data: null }),
      supplierId
        ? admin
            .from("supplier_items")
            .select("item_id, unit_price, price_unit")
            .eq("business_id", businessId)
            .eq("supplier_id", supplierId)
        : Promise.resolve({ data: [] }),
      admin.from("businesses").select("name").eq("id", businessId).maybeSingle(),
      lines[0].ordered_by
        ? admin.from("profiles").select("full_name").eq("id", lines[0].ordered_by).maybeSingle()
        : Promise.resolve({ data: null }),
    ]);

    const items = new Map<string, ItemRow>(((itemsRes.data ?? []) as ItemRow[]).map((i) => [i.id, i]));
    const categories = new Map<string, string>(
      ((categoriesRes.data ?? []) as { id: string; name: string }[]).map((c) => [c.id, c.name]),
    );

    // item_id → { main?, piece? }, exactly like the app's price index.
    const prices = new Map<string, SupplierPrices>();
    for (const row of (pricesRes.data ?? []) as { item_id: string; unit_price: number; price_unit: string }[]) {
      const entry = prices.get(row.item_id) ?? {};
      if (row.price_unit === "piece") entry.piece = Number(row.unit_price);
      else entry.main = Number(row.unit_price);
      prices.set(row.item_id, entry);
    }

    /* ---- render ---------------------------------------------------- */

    const data = buildOrderPdfData({
      batchId,
      businessName: (businessRes.data as { name: string } | null)?.name ?? "העסק",
      lines,
      items,
      categories,
      prices,
      supplier: supplierRes.data as SupplierRow | null,
      orderedByName: (ordererRes.data as { full_name: string | null } | null)?.full_name ?? null,
      now: new Date(),
    });

    const fontBytes = await loadFonts();
    const pdf = await renderOrderPdf({ PDFDocument, rgb, fontkit }, fontBytes, data);

    const name = `הזמנה-${data.supplier.name}-${data.order.number}.pdf`.replace(/[\\/:*?"<>|]/g, "-");
    return new Response(pdf, {
      headers: {
        ...cors,
        "Content-Type": "application/pdf",
        "Content-Disposition":
          `attachment; filename="order-${data.order.number}.pdf"; filename*=UTF-8''${encodeURIComponent(name)}`,
        "Cache-Control": "no-store",
      },
    });
  } catch (e) {
    return json({ error: String(e instanceof Error ? e.message : e) }, 500);
  }
});

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...cors, "Content-Type": "application/json" },
  });
}

/**
 * Rubik — the Hebrew typeface the document is set in.
 *
 * The static TTFs ship inside the @expo-google-fonts packages, which are the
 * only widely mirrored copies of Google's *non-variable* Rubik files (fontkit
 * embeds those far more predictably than a variable font). They are pulled once
 * per isolate and kept in module scope, so only a cold start pays for it.
 */

export type FontWeight = "regular" | "medium" | "bold";

const SOURCES: Record<FontWeight, string[]> = {
  regular: [
    "https://cdn.jsdelivr.net/npm/@expo-google-fonts/rubik@0.2.3/Rubik_400Regular.ttf",
    "https://unpkg.com/@expo-google-fonts/rubik@0.2.3/Rubik_400Regular.ttf",
  ],
  medium: [
    "https://cdn.jsdelivr.net/npm/@expo-google-fonts/rubik@0.2.3/Rubik_500Medium.ttf",
    "https://unpkg.com/@expo-google-fonts/rubik@0.2.3/Rubik_500Medium.ttf",
  ],
  bold: [
    "https://cdn.jsdelivr.net/npm/@expo-google-fonts/rubik@0.2.3/Rubik_700Bold.ttf",
    "https://unpkg.com/@expo-google-fonts/rubik@0.2.3/Rubik_700Bold.ttf",
  ],
};

const cache = new Map<FontWeight, Uint8Array>();

async function download(weight: FontWeight): Promise<Uint8Array> {
  let lastError: unknown = null;
  for (const url of SOURCES[weight]) {
    try {
      const res = await fetch(url, { signal: AbortSignal.timeout(12_000) });
      if (!res.ok) {
        lastError = new Error(`${url} → HTTP ${res.status}`);
        continue;
      }
      const bytes = new Uint8Array(await res.arrayBuffer());
      // A truncated body still parses far enough to produce garbage glyphs, so
      // insist on something that is at least plausibly the whole file.
      if (bytes.byteLength < 20_000) {
        lastError = new Error(`${url} → ${bytes.byteLength} bytes, too small for a TTF`);
        continue;
      }
      return bytes;
    } catch (e) {
      lastError = e;
    }
  }
  throw new Error(`could not load the Hebrew font (${weight}): ${String(lastError)}`);
}

/** All three weights, fetched in parallel on the first call of an isolate. */
export async function loadFonts(): Promise<Record<FontWeight, Uint8Array>> {
  const weights: FontWeight[] = ["regular", "medium", "bold"];
  const missing = weights.filter((w) => !cache.has(w));
  if (missing.length > 0) {
    const fetched = await Promise.all(missing.map(download));
    missing.forEach((w, i) => cache.set(w, fetched[i]));
  }
  return {
    regular: cache.get("regular")!,
    medium: cache.get("medium")!,
    bold: cache.get("bold")!,
  };
}

/**
 * Database rows → document data.
 *
 * Everything in here is a deliberate port of the matching helper in
 * src/api/inventory.ts and src/api/suppliers.ts, so the sheet the supplier gets
 * always shows the same quantities and totals as the screen the manager
 * ordered from. Kept apart from index.ts so it can be exercised without a
 * Supabase connection.
 */

import { formatShekel, type OrderPdfData, type OrderPdfLine } from "./render.ts";

const HE_DAYS = ["ראשון", "שני", "שלישי", "רביעי", "חמישי", "שישי", "שבת"];

export interface OrderRow {
  id: string;
  item_id: string;
  quantity: number;
  received_quantity: number | null;
  status: "requested" | "ordered" | "received";
  batch_id: string | null;
  supplier_id: string | null;
  ordered_by: string | null;
  created_at: string;
}

export interface ItemRow {
  id: string;
  name: string;
  unit: string | null;
  units_per_package: number | null;
  piece_unit: string | null;
  barcode: string | null;
  category_id: string | null;
}

export interface SupplierRow {
  name: string;
  phone: string | null;
  tax_id: string | null;
  notes: string | null;
  delivery_days: number[] | null;
}

export interface SupplierPrices {
  main?: number;
  piece?: number;
}

export interface BuildInput {
  batchId: string;
  businessName: string;
  /** Every row of the batch, in any order. */
  lines: OrderRow[];
  items: Map<string, ItemRow>;
  /** category_id → name */
  categories: Map<string, string>;
  /** item_id → the supplier's prices for it */
  prices: Map<string, SupplierPrices>;
  supplier: SupplierRow | null;
  orderedByName: string | null;
  now: Date;
}

export function buildOrderPdfData(input: BuildInput): OrderPdfData {
  const { items, categories, prices } = input;

  const sorted = [...input.lines].sort((a, b) =>
    (items.get(a.item_id)?.name ?? "").localeCompare(items.get(b.item_id)?.name ?? "", "he"),
  );

  let sum = 0;
  let unpriced = 0;
  // Kept per unit: adding 12.5 ק״ג to 4 ארגז would be a number that means
  // nothing to whoever loads the truck.
  const byUnit = new Map<string, number>();

  const pdfLines: OrderPdfLine[] = sorted.map((row) => {
    const item = items.get(row.item_id) ?? null;
    const qty = billableQty(row);
    const pack = item?.units_per_package ?? null;
    const unitPrice = mainUnitPrice(prices.get(row.item_id), pack);
    const total = unitPrice > 0 ? Math.round(qty * unitPrice * 100) / 100 : 0;

    const unitLabel = item?.unit?.trim() || "יחידות";
    byUnit.set(unitLabel, (byUnit.get(unitLabel) ?? 0) + qty);
    if (unitPrice > 0) sum += total;
    else unpriced += 1;

    const meta = [
      item?.category_id ? categories.get(item.category_id) : null,
      packLabel(item),
      item?.barcode,
    ]
      .filter(Boolean)
      .join(" · ");

    // The pieces line only adds something once whole packages are involved —
    // "3 ארגז" is worth restating as "72 בקבוק", "5 בקבוק" is not.
    const totalPieces = pack && pack > 0 ? Math.round(qty * pack) : 0;
    const wholePacks = pack && pack > 0 ? Math.floor(totalPieces / pack) : 0;
    const ordered = Number(row.quantity);

    return {
      name: item?.name ?? "מוצר שנמחק",
      meta,
      qty: formatQty(qty, item),
      qtySub: wholePacks > 0 ? `${trimNum(totalPieces)} ${item?.piece_unit?.trim() || "יחידות"}` : "",
      price: unitPrice > 0 ? formatShekel(unitPrice) : "",
      priceUnit: unitPrice > 0 ? `ל${item?.unit?.trim() || "יחידה"}` : "",
      total,
      receivedNote:
        row.status === "received" && qty !== ordered
          ? `התקבל ${trimNum(qty)} מתוך ${trimNum(ordered)}`
          : "",
    };
  });

  const allReceived = input.lines.every((l) => l.status === "received");
  const anyReceived = input.lines.some((l) => l.status === "received");
  const createdAt = new Date(sorted[0]?.created_at ?? input.now.toISOString());
  const supplier = input.supplier;

  return {
    businessName: input.businessName,
    supplier: {
      name: supplier?.name ?? "ספק לא הוגדר",
      phone: supplier?.phone?.trim() ?? "",
      taxId: supplier?.tax_id?.trim() ?? "",
      deliveryDays: deliveryDaysLabel(supplier?.delivery_days),
      notes: supplier?.notes?.trim() ?? "",
    },
    order: {
      number: shortId(input.batchId),
      date: heDate(createdAt),
      time: heTime(createdAt),
      orderedBy: input.orderedByName?.trim() || "לא ידוע",
      statusLabel: allReceived ? "התקבל" : anyReceived ? "התקבל חלקית" : "בהזמנה",
      statusTone: allReceived ? "received" : anyReceived ? "partial" : "open",
    },
    lines: pdfLines,
    totals: {
      unitsLabel: unitsBreakdown(byUnit),
      sum: formatShekel(sum),
      unpriced,
    },
    generatedAt: `${heDate(input.now)}, ${heTime(input.now)}`,
  };
}

/** "16 ארגז · 30.9 ק״ג · 2 קרטון" — the biggest units first. */
function unitsBreakdown(byUnit: Map<string, number>): string {
  const parts = [...byUnit.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([unit, qty]) => `${trimNum(qty)} ${unit}`);
  if (parts.length <= 4) return parts.join(" · ");
  return `${parts.slice(0, 4).join(" · ")} ועוד`;
}

/** A received line is billed for what actually arrived. */
export function billableQty(row: Pick<OrderRow, "status" | "quantity" | "received_quantity">): number {
  if (row.status === "received") return Number(row.received_quantity ?? row.quantity);
  return Number(row.quantity);
}

/** Prefers the main-unit price, falling back to piece price × pack size. */
export function mainUnitPrice(entry: SupplierPrices | undefined, pack: number | null): number {
  if (!entry) return 0;
  if (entry.main != null && entry.main > 0) return entry.main;
  if (entry.piece != null && entry.piece > 0 && pack && pack > 0) {
    return Math.round(entry.piece * pack * 100) / 100;
  }
  return 0;
}

/** "7 ארגז + 2 בקבוק" when the product has a pack size, "2.5 ק״ג" when it does not. */
export function formatQty(qty: number, item: ItemRow | null): string {
  const unit = item?.unit?.trim() ?? "";
  const pack = item?.units_per_package ?? 0;
  if (!pack || pack <= 0) return unit ? `${trimNum(qty)} ${unit}` : trimNum(qty);

  const pieceUnit = item?.piece_unit?.trim() || "יחידות";
  const totalPieces = Math.round(qty * pack);
  const packages = Math.floor(totalPieces / pack);
  const pieces = totalPieces % pack;
  if (packages === 0 && pieces === 0) return unit ? `0 ${unit}` : "0";
  if (packages === 0) return `${pieces} ${pieceUnit}`;
  if (pieces === 0) return unit ? `${packages} ${unit}` : String(packages);
  return unit ? `${packages} ${unit} + ${pieces} ${pieceUnit}` : `${packages} + ${pieces} ${pieceUnit}`;
}

/** "ארגז של 24 בקבוק" — the quiet line under the product name. */
export function packLabel(item: ItemRow | null): string {
  if (!item) return "";
  const pack = item.units_per_package ?? 0;
  const unit = item.unit?.trim() || "יחידה";
  if (pack > 0) return `${unit} של ${trimNum(pack)} ${item.piece_unit?.trim() || "יחידות"}`;
  return unit;
}

export function deliveryDaysLabel(days: number[] | null | undefined): string {
  if (!days?.length) return "לא הוגדר";
  const valid = [...new Set(days.filter((d) => d >= 0 && d <= 6))].sort((a, b) => a - b);
  if (valid.length === 0) return "לא הוגדר";
  return valid.map((d) => `יום ${HE_DAYS[d]}`).join(", ");
}

/** Quantities are numeric(12,2): round off float drift and drop trailing zeros. */
function trimNum(n: number): string {
  return String(Math.round(n * 100) / 100);
}

/** The first block of the batch uuid — short enough to read out over the phone. */
function shortId(batchId: string): string {
  return batchId.split("-")[0].toUpperCase();
}

function heDate(d: Date): string {
  return d.toLocaleDateString("he-IL", { day: "numeric", month: "short", year: "numeric" });
}

function heTime(d: Date): string {
  return d.toLocaleTimeString("he-IL", { hour: "2-digit", minute: "2-digit" });
}

/**
 * Hebrew text for pdf-lib.
 *
 * pdf-lib hands every string to fontkit, and fontkit reverses the glyphs of a
 * string whose dominant script is right-to-left. That is the right thing for a
 * single Hebrew word and the wrong thing for anything mixed: given
 * "קוקה קולה 1.5 ליטר" it flips the number too, and a barcode comes out back to
 * front. fontkit is not a bidi engine — it only knows "this string is Hebrew".
 *
 * So the ordering is resolved here instead, with a reduced version of the bidi
 * algorithm (UAX #9): classify the directional runs, resolve the neutrals
 * between them, and hand back the runs already ordered left-to-right. Each run
 * is then drawn as its own string at its own x, which leaves fontkit with a
 * single-direction string it cannot get wrong.
 */

type Dir = "R" | "L" | "N";

export interface TextRun {
  /** Logical order — fontkit reverses it when the run is RTL. */
  text: string;
  rtl: boolean;
}

/** Bidi_Mirrored characters — a "(" inside an RTL run is drawn as ")". */
const MIRROR: Record<string, string> = {
  "(": ")",
  ")": "(",
  "[": "]",
  "]": "[",
  "{": "}",
  "}": "{",
  "<": ">",
  ">": "<",
  "«": "»",
  "»": "«",
};

function dirOf(cp: number): Dir {
  // Hebrew, Hebrew presentation forms, Arabic — strong RTL
  if (
    (cp >= 0x0590 && cp <= 0x05ff) ||
    (cp >= 0x0600 && cp <= 0x08ff) ||
    (cp >= 0xfb1d && cp <= 0xfdff) ||
    (cp >= 0xfe70 && cp <= 0xfeff)
  ) {
    return "R";
  }
  // Digits, Latin, Greek, Cyrillic — treated as one LTR class. Merging digits
  // into L (rather than the spec's separate EN class) is what keeps "1.5 ליטר"
  // and a 13-digit barcode in one piece, which is all this document needs.
  if (
    (cp >= 0x0030 && cp <= 0x0039) ||
    (cp >= 0x0041 && cp <= 0x005a) ||
    (cp >= 0x0061 && cp <= 0x007a) ||
    (cp >= 0x00c0 && cp <= 0x024f) ||
    (cp >= 0x0370 && cp <= 0x04ff)
  ) {
    return "L";
  }
  return "N";
}

/** Marks that must stay glued to the character in front of them. */
function isCombining(cp: number): boolean {
  return (
    (cp >= 0x0300 && cp <= 0x036f) || // combining diacriticals
    (cp >= 0x0591 && cp <= 0x05bd) || // ta'amim + most nikud
    cp === 0x05bf ||
    cp === 0x05c1 ||
    cp === 0x05c2 ||
    cp === 0x05c4 ||
    cp === 0x05c5 ||
    cp === 0x05c7 ||
    cp === 0x200d ||
    (cp >= 0xfe00 && cp <= 0xfe0f)
  );
}

/**
 * Split into grapheme-ish clusters (base character + its combining marks) so
 * nothing ever separates nikud from the letter it sits under.
 */
export function toClusters(text: string): string[] {
  const clusters: string[] = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0)!;
    if (clusters.length > 0 && isCombining(cp)) clusters[clusters.length - 1] += ch;
    else clusters.push(ch);
  }
  return clusters;
}

/**
 * Split one already-wrapped line into directional runs, ordered left-to-right
 * for a right-to-left paragraph. A pure-LTR string (barcode, phone number,
 * price) comes back as a single untouched run.
 */
export function toRuns(logical: string): TextRun[] {
  const clusters = toClusters(logical);
  if (clusters.length === 0) return [];

  const dirs = clusters.map((c) => dirOf(c.codePointAt(0)!));

  // Neutrals take the direction of their surroundings when both sides agree,
  // and the paragraph direction (RTL) otherwise. A run at either end of the
  // line sees the paragraph direction as its missing neighbour.
  for (let i = 0; i < dirs.length; i++) {
    if (dirs[i] !== "N") continue;
    let j = i;
    while (j < dirs.length && dirs[j] === "N") j++;
    const before: Dir = i > 0 ? dirs[i - 1] : "R";
    const after: Dir = j < dirs.length ? dirs[j] : "R";
    const resolved: Dir = before === after ? before : "R";
    for (let k = i; k < j; k++) dirs[k] = resolved;
    i = j - 1;
  }

  const runs: TextRun[] = [];
  for (let i = 0; i < clusters.length; ) {
    const dir = dirs[i];
    const items: string[] = [];
    while (i < clusters.length && dirs[i] === dir) {
      const cluster = clusters[i++];
      // fontkit reverses positions but never mirrors, so brackets that landed
      // in an RTL run are swapped here instead.
      items.push(dir === "R" ? (MIRROR[cluster] ?? cluster) : cluster);
    }
    runs.push({ text: items.join(""), rtl: dir === "R" });
  }

  // The first logical run sits furthest right, so lay them out back to front.
  return runs.reverse();
}

/**
 * The same reordering, but broken all the way down to single clusters in
 * left-to-right paint order. Used for letter-spaced labels, which are drawn one
 * cluster at a time — a lone cluster is a single glyph fontkit cannot reorder.
 */
export function toVisualClusters(logical: string): string[] {
  const out: string[] = [];
  for (const run of toRuns(logical)) {
    const clusters = toClusters(run.text);
    if (run.rtl) clusters.reverse();
    out.push(...clusters);
  }
  return out;
}

/**
 * Drop anything the embedded font cannot draw. Rubik covers Hebrew, Latin and
 * the punctuation used here but not emoji, arrows or geometric shapes, and an
 * uncovered code point would come out as a hollow .notdef box.
 */
export function sanitize(raw: string | null | undefined): string {
  if (!raw) return "";
  let out = "";
  for (const ch of raw) {
    const cp = ch.codePointAt(0)!;
    if (cp === 0x000a || cp === 0x000d) {
      out += "\n";
      continue;
    }
    if (cp === 0x0009) {
      out += " ";
      continue;
    }
    if (cp < 0x20) continue; // other control characters
    if (cp <= 0x007e) {
      out += ch;
      continue;
    }
    const keep =
      (cp >= 0x00a0 && cp <= 0x024f) || // Latin-1 + Latin Extended A/B
      (cp >= 0x0370 && cp <= 0x04ff) || // Greek + Cyrillic
      (cp >= 0x0590 && cp <= 0x05f4) || // Hebrew
      (cp >= 0x2010 && cp <= 0x2027) || // dashes, quotes, bullet, ellipsis
      cp === 0x20aa || // ₪
      cp === 0x20ac; // €
    if (keep) out += ch;
  }
  return out;
}

/** Collapse whitespace and trim — table cells are single-line. */
export function oneLine(raw: string | null | undefined): string {
  return sanitize(raw).replace(/\s+/g, " ").trim();
}

/**
 * The purchase-order document.
 *
 * pdf-lib is handed in rather than imported so the exact same layout code runs
 * under Deno (the edge function) and under Node (the render smoke test).
 *
 * Everything here works in top-down coordinates — `top` is the distance from
 * the top of the page — and the few helpers at the bottom of this file convert
 * to PDF's bottom-left origin at the last moment.
 */

import { oneLine, sanitize, toClusters, toRuns, toVisualClusters } from "./rtl.ts";

/* eslint-disable @typescript-eslint/no-explicit-any */
type Page = any;
type Font = any;
type Color = any;

export interface PdfLib {
  PDFDocument: any;
  rgb: (r: number, g: number, b: number) => Color;
  fontkit: any;
}

export interface OrderPdfLine {
  name: string;
  /** Category · pack size · barcode — the quiet second line under the name. */
  meta: string;
  /** "2 ארגז + 3 בקבוק" */
  qty: string;
  /** Total pieces, when the product is packaged. */
  qtySub: string;
  /** "₪120" or "" when the supplier has no price for this product. */
  price: string;
  /** "לארגז" */
  priceUnit: string;
  /** Line total in shekels; 0 when unpriced. */
  total: number;
  /** Set when the delivered quantity differed from what was ordered. */
  receivedNote: string;
}

export interface OrderPdfData {
  businessName: string;
  supplier: {
    name: string;
    phone: string;
    taxId: string;
    deliveryDays: string;
    notes: string;
  };
  order: {
    number: string;
    date: string;
    time: string;
    orderedBy: string;
    statusLabel: string;
    statusTone: "open" | "received" | "partial";
  };
  lines: OrderPdfLine[];
  totals: {
    unitsLabel: string;
    sum: string;
    /** How many lines the supplier has no price for — surfaced, never hidden. */
    unpriced: number;
  };
  generatedAt: string;
}

/* ------------------------------------------------------------------ */
/* Page geometry                                                       */
/* ------------------------------------------------------------------ */

const PAGE_W = 595.28;
const PAGE_H = 841.89;
const MARGIN = 42;
const CONTENT_W = PAGE_W - MARGIN * 2;
const RIGHT = PAGE_W - MARGIN;

const HERO_H = 176;
const RIBBON_H = 58;
const ROW_H = 36;
const HEAD_H = 30;
const CELL_PAD = 10;
/** Rows may not cross this line; the footer lives below it. */
const BODY_BOTTOM = PAGE_H - 74;
/** Baseline sits this fraction of the font size below the top of a line box. */
const BASELINE = 0.78;

const COLUMNS = [
  { key: "idx", w: 28 },
  { key: "name", w: 217 },
  { key: "qty", w: 88 },
  { key: "price", w: 88 },
  { key: "total", w: 90 },
] as const;

type ColKey = (typeof COLUMNS)[number]["key"];

/** Right edge of every column, walking inwards from the right page margin. */
const COL_RIGHT: Record<ColKey, number> = (() => {
  const map = {} as Record<ColKey, number>;
  let edge = RIGHT;
  for (const col of COLUMNS) {
    map[col.key] = edge;
    edge -= col.w;
  }
  return map;
})();

const COL_W: Record<ColKey, number> = Object.fromEntries(
  COLUMNS.map((c) => [c.key, c.w]),
) as Record<ColKey, number>;

/* ------------------------------------------------------------------ */
/* Palette — the app's tokens, nudged for print contrast               */
/* ------------------------------------------------------------------ */

function hex(rgb: PdfLib["rgb"], value: string): Color {
  const n = parseInt(value.slice(1), 16);
  return rgb(((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255);
}

function palette(rgb: PdfLib["rgb"]) {
  return {
    ink: hex(rgb, "#121a24"),
    inkDeep: hex(rgb, "#0b0e16"),
    white: hex(rgb, "#ffffff"),
    text: hex(rgb, "#121a24"),
    text2: hex(rgb, "#5a636e"),
    text3: hex(rgb, "#949ca6"),
    text4: hex(rgb, "#b3b9c1"),
    border: hex(rgb, "#e4e6eb"),
    hair: hex(rgb, "#eef0f2"),
    zebra: hex(rgb, "#fafbfc"),
    band: hex(rgb, "#f4f5f7"),
    panel: hex(rgb, "#f7f8fa"),
    card: hex(rgb, "#fcfcfd"),
    success: hex(rgb, "#00a05e"),
    successBg: hex(rgb, "#e4f6ee"),
    warning: hex(rgb, "#a56a06"),
    warningBg: hex(rgb, "#fdf0d9"),
    info: hex(rgb, "#2f6fd0"),
    infoBg: hex(rgb, "#e6eefb"),
  };
}

type Palette = ReturnType<typeof palette>;
type Fonts = { reg: Font; med: Font; bold: Font };

/* ------------------------------------------------------------------ */
/* Drawing primitives (top-down coordinates)                           */
/* ------------------------------------------------------------------ */

const K = 0.5522847498307936;

/** Rounded-rectangle path in SVG space, with per-corner radii. */
function roundedPath(w: number, h: number, r: number | [number, number, number, number]): string {
  const [tl, tr, br, bl] = typeof r === "number" ? [r, r, r, r] : r;
  const lim = Math.min(w, h) / 2;
  const a = Math.min(tl, lim);
  const b = Math.min(tr, lim);
  const c = Math.min(br, lim);
  const d = Math.min(bl, lim);
  return [
    `M ${a} 0`,
    `H ${w - b}`,
    `C ${w - b + b * K} 0 ${w} ${b - b * K} ${w} ${b}`,
    `V ${h - c}`,
    `C ${w} ${h - c + c * K} ${w - c + c * K} ${h} ${w - c} ${h}`,
    `H ${d}`,
    `C ${d - d * K} ${h} 0 ${h - d + d * K} 0 ${h - d}`,
    `V ${a}`,
    `C 0 ${a - a * K} ${a - a * K} 0 ${a} 0`,
    "Z",
  ].join(" ");
}

interface BoxOpts {
  left: number;
  top: number;
  w: number;
  h: number;
  radius?: number | [number, number, number, number];
  fill?: Color;
  stroke?: Color;
  strokeWidth?: number;
  opacity?: number;
}

function box(page: Page, o: BoxOpts) {
  if (o.radius === undefined || o.radius === 0) {
    page.drawRectangle({
      x: o.left,
      y: PAGE_H - o.top - o.h,
      width: o.w,
      height: o.h,
      color: o.fill,
      borderColor: o.stroke,
      borderWidth: o.stroke ? (o.strokeWidth ?? 1) : undefined,
      opacity: o.opacity,
      borderOpacity: o.opacity,
    });
    return;
  }
  page.drawSvgPath(roundedPath(o.w, o.h, o.radius), {
    x: o.left,
    y: PAGE_H - o.top,
    color: o.fill,
    borderColor: o.stroke,
    borderWidth: o.stroke ? (o.strokeWidth ?? 1) : 0,
    opacity: o.opacity,
    borderOpacity: o.opacity,
  });
}

function hairline(page: Page, left: number, top: number, w: number, color: Color, opacity?: number) {
  page.drawRectangle({
    x: left,
    y: PAGE_H - top,
    width: w,
    height: 0.7,
    color,
    opacity,
  });
}

interface TextOpts {
  size: number;
  font: Font;
  color: Color;
  /** "right" anchors the string's right edge at `x` — the RTL default. */
  align?: "right" | "left" | "center";
  opacity?: number;
  maxWidth?: number;
  tracking?: number;
}

/**
 * The pieces a line is painted from, left to right. Without letter spacing that
 * is one string per directional run; with it, one string per cluster, because
 * the gap has to be opened between every pair of glyphs.
 */
function segmentsOf(logical: string, tracking?: number): string[] {
  if (tracking) return toVisualClusters(logical);
  return toRuns(logical).map((run) => run.text);
}

function measure(segments: string[], o: Pick<TextOpts, "size" | "font" | "tracking">): number {
  let w = 0;
  for (const segment of segments) w += o.font.widthOfTextAtSize(segment, o.size);
  if (o.tracking) w += o.tracking * Math.max(0, segments.length - 1);
  return w;
}

/**
 * Shorten a *logical* string until it fits, keeping the ellipsis on the reading
 * end (visually the left, in Hebrew).
 */
function fit(logical: string, o: Pick<TextOpts, "size" | "font" | "tracking" | "maxWidth">): string[] {
  const full = segmentsOf(logical, o.tracking);
  if (o.maxWidth === undefined || measure(full, o) <= o.maxWidth) return full;
  const parts = toClusters(logical);
  while (parts.length > 0) {
    parts.pop();
    const candidate = segmentsOf(parts.join("").trimEnd() + "…", o.tracking);
    if (measure(candidate, o) <= o.maxWidth) return candidate;
  }
  return [];
}

/** Draw one line of Hebrew/mixed text. Returns the width actually painted. */
function text(page: Page, raw: string, x: number, top: number, o: TextOpts): number {
  const logical = oneLine(raw);
  if (!logical) return 0;
  const segments = fit(logical, o);
  if (segments.length === 0) return 0;

  const w = measure(segments, o);
  const y = PAGE_H - top - o.size * BASELINE;
  let cursor = o.align === "left" ? x : o.align === "center" ? x - w / 2 : x - w;

  for (const segment of segments) {
    page.drawText(segment, { x: cursor, y, size: o.size, font: o.font, color: o.color, opacity: o.opacity });
    cursor += o.font.widthOfTextAtSize(segment, o.size) + (o.tracking ?? 0);
  }
  return w;
}

/** Greedy word wrap over the logical string; each line is reordered on its own. */
function wrap(raw: string, o: Pick<TextOpts, "size" | "font">, maxWidth: number, maxLines: number): string[] {
  const source = sanitize(raw).replace(/[ \t]+/g, " ").trim();
  if (!source) return [];
  const out: string[] = [];

  for (const paragraph of source.split("\n")) {
    const words = paragraph.trim().split(" ").filter(Boolean);
    let line = "";
    for (const word of words) {
      const next = line ? `${line} ${word}` : word;
      if (measure(segmentsOf(next), o) <= maxWidth || !line) {
        line = next;
        continue;
      }
      out.push(line);
      line = word;
      if (out.length === maxLines) break;
    }
    if (out.length >= maxLines) break;
    if (line) out.push(line);
    if (out.length >= maxLines) break;
  }

  if (out.length > maxLines) out.length = maxLines;
  // The last line absorbs the ellipsis when the text was cut short.
  const total = source.split(/\s+/).length;
  const shown = out.join(" ").split(/\s+/).length;
  if (shown < total && out.length > 0) out[out.length - 1] += "…";
  return out;
}

/** Small filled pill with a leading dot — the status chip. */
function pill(
  page: Page,
  label: string,
  right: number,
  top: number,
  fonts: Fonts,
  fill: Color,
  fg: Color,
  opts: { size?: number; dot?: Color } = {},
) {
  const size = opts.size ?? 8.5;
  const o = { size, font: fonts.bold, color: fg };
  const w = measure(segmentsOf(oneLine(label)), o);
  const dotW = opts.dot ? 11 : 0;
  const boxW = w + dotW + 22;
  const boxH = size + 12;
  box(page, { left: right - boxW, top, w: boxW, h: boxH, radius: boxH / 2, fill });
  if (opts.dot) {
    page.drawCircle({ x: right - 11, y: PAGE_H - top - boxH / 2, size: 2.6, color: opts.dot });
  }
  text(page, label, right - 11 - dotW, top + 6, o);
  return boxH;
}

/* ------------------------------------------------------------------ */
/* Document                                                            */
/* ------------------------------------------------------------------ */

export async function renderOrderPdf(
  lib: PdfLib,
  fontBytes: { regular: Uint8Array; medium: Uint8Array; bold: Uint8Array },
  data: OrderPdfData,
): Promise<Uint8Array> {
  const pdf = await lib.PDFDocument.create();
  pdf.registerFontkit(lib.fontkit);

  const fonts: Fonts = {
    reg: await pdf.embedFont(fontBytes.regular, { subset: true }),
    med: await pdf.embedFont(fontBytes.medium, { subset: true }),
    bold: await pdf.embedFont(fontBytes.bold, { subset: true }),
  };
  const c = palette(lib.rgb);

  pdf.setTitle(`הזמנה ${data.order.number} — ${data.supplier.name}`);
  pdf.setAuthor(data.businessName);
  pdf.setSubject(`הזמנת רכש מהספק ${data.supplier.name}`);
  pdf.setCreator(data.businessName);
  pdf.setProducer("Business Management");
  pdf.setLanguage("he-IL");
  pdf.setCreationDate(new Date());

  const pages: Page[] = [];
  const newPage = (): Page => {
    const page = pdf.addPage([PAGE_W, PAGE_H]);
    pages.push(page);
    return page;
  };

  let page = newPage();
  drawHero(page, fonts, c, data);
  drawFactCards(page, fonts, c, data, 202);

  let top = 296;
  top = drawTableHead(page, fonts, c, top);

  data.lines.forEach((line, i) => {
    if (top + ROW_H > BODY_BOTTOM) {
      page = newPage();
      drawRibbon(page, fonts, c, data);
      top = drawTableHead(page, fonts, c, RIBBON_H + 26);
    }
    drawRow(page, fonts, c, line, i, top);
    top += ROW_H;
  });

  hairline(page, MARGIN, top, CONTENT_W, c.border);
  top += 26;

  if (top + SUMMARY_H > BODY_BOTTOM) {
    page = newPage();
    drawRibbon(page, fonts, c, data);
    top = RIBBON_H + 30;
  }
  drawSummary(page, fonts, c, data, top);

  pages.forEach((p, i) => drawFooter(p, fonts, c, data, i + 1, pages.length));

  return await pdf.save();
}

/* ---- page 1 hero ------------------------------------------------- */

function drawHero(page: Page, fonts: Fonts, c: Palette, data: OrderPdfData) {
  box(page, { left: 0, top: 0, w: PAGE_W, h: HERO_H, fill: c.ink });

  // Depth: two oversized, barely-there discs bleeding off the left edge.
  page.drawCircle({ x: 22, y: PAGE_H - 24, size: 132, color: c.white, opacity: 0.04 });
  page.drawCircle({ x: 150, y: PAGE_H - 196, size: 116, color: c.white, opacity: 0.028 });
  page.drawCircle({ x: PAGE_W - 40, y: PAGE_H - 178, size: 92, color: c.white, opacity: 0.022 });

  // A hand-built gradient rule along the bottom edge: bright under the title,
  // fading out towards the left (a real PDF gradient needs a shading
  // dictionary). Every band ends at the right edge and they stack, so the alpha
  // builds up smoothly instead of leaving a seam between neighbouring steps.
  const steps = 26;
  for (let i = 0; i < steps; i++) {
    const w = PAGE_W * Math.pow((i + 1) / steps, 2.1);
    box(page, {
      left: PAGE_W - w,
      top: HERO_H - 2.6,
      w,
      h: 2.6,
      fill: c.white,
      opacity: 0.022,
    });
  }

  text(page, "הזמנת רכש", RIGHT, 40, {
    size: 8,
    font: fonts.med,
    color: c.white,
    opacity: 0.55,
    tracking: 2.1,
  });
  text(page, data.businessName, RIGHT, 56, {
    size: 25,
    font: fonts.bold,
    color: c.white,
    maxWidth: 300,
  });
  text(page, `הזמנה לספק · ${data.supplier.name}`, RIGHT, 94, {
    size: 11,
    font: fonts.reg,
    color: c.white,
    opacity: 0.72,
    maxWidth: 300,
  });

  const tone =
    data.order.statusTone === "received"
      ? { fill: c.success, fg: c.white }
      : data.order.statusTone === "partial"
        ? { fill: c.warning, fg: c.white }
        : { fill: c.white, fg: c.ink };
  pill(page, data.order.statusLabel, RIGHT, 118, fonts, tone.fill, tone.fg, { dot: tone.fg });

  // Order card, left column.
  const cardW = 208;
  const cardL = MARGIN;
  box(page, {
    left: cardL,
    top: 44,
    w: cardW,
    h: 88,
    radius: 14,
    fill: c.white,
    opacity: 0.075,
  });
  box(page, {
    left: cardL,
    top: 44,
    w: cardW,
    h: 88,
    radius: 14,
    stroke: c.white,
    strokeWidth: 0.8,
    opacity: 0.17,
  });

  const cardRight = cardL + cardW - 16;
  text(page, "מספר הזמנה", cardRight, 56, {
    size: 7.2,
    font: fonts.med,
    color: c.white,
    opacity: 0.5,
    tracking: 1.1,
  });
  text(page, data.order.number, cardRight, 68, {
    size: 14,
    font: fonts.bold,
    color: c.white,
    maxWidth: cardW - 32,
  });
  hairline(page, cardL + 16, 90, cardW - 32, c.white, 0.16);
  text(page, "תאריך ההזמנה", cardRight, 98, {
    size: 7.2,
    font: fonts.med,
    color: c.white,
    opacity: 0.5,
    tracking: 1.1,
  });
  text(page, `${data.order.date} · ${data.order.time}`, cardRight, 110, {
    size: 10.5,
    font: fonts.med,
    color: c.white,
    opacity: 0.92,
    maxWidth: cardW - 32,
  });
}

/* ---- continuation pages ------------------------------------------ */

function drawRibbon(page: Page, fonts: Fonts, c: Palette, data: OrderPdfData) {
  box(page, { left: 0, top: 0, w: PAGE_W, h: RIBBON_H, fill: c.ink });
  text(page, `${data.businessName} · הזמנה ${data.order.number}`, RIGHT, 20, {
    size: 11,
    font: fonts.bold,
    color: c.white,
    maxWidth: 330,
  });
  text(page, `המשך · ${data.supplier.name}`, MARGIN, 22, {
    size: 9,
    font: fonts.reg,
    color: c.white,
    opacity: 0.6,
    align: "left",
    maxWidth: 150,
  });
}

/* ---- fact cards --------------------------------------------------- */

function drawFactCards(page: Page, fonts: Fonts, c: Palette, data: OrderPdfData, top: number) {
  const gap = 12;
  const w = (CONTENT_W - gap * 2) / 3;
  const h = 76;

  const cards: { label: string; value: string; sub: string }[] = [
    {
      label: "ספק",
      value: data.supplier.name,
      sub: data.supplier.phone || "לא הוזן טלפון",
    },
    {
      label: "ימי אספקה",
      value: data.supplier.deliveryDays,
      sub: data.supplier.taxId ? `ח.פ / עוסק ${data.supplier.taxId}` : "לא הוזן ח.פ / עוסק",
    },
    {
      label: "הוזמן על ידי",
      value: data.order.orderedBy,
      sub: `${data.lines.length} שורות בהזמנה`,
    },
  ];

  cards.forEach((card, i) => {
    const left = RIGHT - w - i * (w + gap);
    box(page, { left, top, w, h, radius: 13, fill: c.card });
    box(page, { left, top, w, h, radius: 13, stroke: c.border, strokeWidth: 0.8 });
    // A short accent tick in the card's top-right corner keeps the row from
    // reading as three empty boxes.
    box(page, { left: left + w - 14 - 18, top: top + 14, w: 18, h: 2.2, radius: 1.1, fill: c.ink, opacity: 0.85 });

    const right = left + w - 14;
    text(page, card.label, right, top + 24, {
      size: 7.2,
      font: fonts.med,
      color: c.text3,
      tracking: 1,
    });
    text(page, card.value, right, top + 36, {
      size: 12,
      font: fonts.bold,
      color: c.text,
      maxWidth: w - 28,
    });
    text(page, card.sub, right, top + 54, {
      size: 8.6,
      font: fonts.reg,
      color: c.text2,
      maxWidth: w - 28,
    });
  });
}

/* ---- table -------------------------------------------------------- */

function drawTableHead(page: Page, fonts: Fonts, c: Palette, top: number): number {
  box(page, {
    left: MARGIN,
    top,
    w: CONTENT_W,
    h: HEAD_H,
    radius: [10, 10, 0, 0],
    fill: c.band,
  });
  hairline(page, MARGIN, top + HEAD_H, CONTENT_W, c.border);

  const labels: Record<ColKey, string> = {
    idx: "#",
    name: "מוצר",
    qty: "כמות",
    price: "מחיר ליחידה",
    total: "סה״כ",
  };
  const opts: TextOpts = { size: 7.8, font: fonts.bold, color: c.text2, tracking: 0.7 };
  for (const col of COLUMNS) {
    if (col.key === "idx") {
      text(page, labels.idx, COL_RIGHT.idx - COL_W.idx / 2, top + 11, { ...opts, align: "center" });
      continue;
    }
    text(page, labels[col.key], COL_RIGHT[col.key] - CELL_PAD, top + 11, {
      ...opts,
      maxWidth: col.w - CELL_PAD * 2,
    });
  }
  return top + HEAD_H;
}

function drawRow(page: Page, fonts: Fonts, c: Palette, line: OrderPdfLine, index: number, top: number) {
  if (index % 2 === 1) {
    box(page, { left: MARGIN, top, w: CONTENT_W, h: ROW_H, fill: c.zebra });
  }
  hairline(page, MARGIN, top + ROW_H, CONTENT_W, c.hair);

  text(page, String(index + 1), COL_RIGHT.idx - COL_W.idx / 2, top + 13, {
    size: 8.5,
    font: fonts.med,
    color: c.text4,
    align: "center",
  });

  const twoLine = !!line.meta;
  text(page, line.name, COL_RIGHT.name - CELL_PAD, top + (twoLine ? 8 : 13), {
    size: 10.5,
    font: fonts.bold,
    color: c.text,
    maxWidth: COL_W.name - CELL_PAD * 2,
  });
  if (twoLine) {
    text(page, line.meta, COL_RIGHT.name - CELL_PAD, top + 22, {
      size: 7.8,
      font: fonts.reg,
      color: c.text3,
      maxWidth: COL_W.name - CELL_PAD * 2,
    });
  }

  text(page, line.qty, COL_RIGHT.qty - CELL_PAD, top + (line.qtySub ? 8 : 13), {
    size: 10.5,
    font: fonts.med,
    color: c.text,
    maxWidth: COL_W.qty - CELL_PAD * 2,
  });
  if (line.qtySub) {
    text(page, line.qtySub, COL_RIGHT.qty - CELL_PAD, top + 22, {
      size: 7.8,
      font: fonts.reg,
      color: c.text3,
      maxWidth: COL_W.qty - CELL_PAD * 2,
    });
  }

  if (line.price) {
    text(page, line.price, COL_RIGHT.price - CELL_PAD, top + 8, {
      size: 10.5,
      font: fonts.med,
      color: c.text,
      maxWidth: COL_W.price - CELL_PAD * 2,
    });
    text(page, line.priceUnit, COL_RIGHT.price - CELL_PAD, top + 22, {
      size: 7.8,
      font: fonts.reg,
      color: c.text3,
      maxWidth: COL_W.price - CELL_PAD * 2,
    });
  } else {
    text(page, "ללא מחיר", COL_RIGHT.price - CELL_PAD, top + 13, {
      size: 9,
      font: fonts.reg,
      color: c.warning,
      maxWidth: COL_W.price - CELL_PAD * 2,
    });
  }

  text(page, line.total > 0 ? formatShekel(line.total) : "—", COL_RIGHT.total - CELL_PAD, top + (line.receivedNote ? 8 : 13), {
    size: 11,
    font: fonts.bold,
    color: line.total > 0 ? c.text : c.text4,
    maxWidth: COL_W.total - CELL_PAD * 2,
  });
  if (line.receivedNote) {
    text(page, line.receivedNote, COL_RIGHT.total - CELL_PAD, top + 22, {
      size: 7.6,
      font: fonts.reg,
      color: c.warning,
      maxWidth: COL_W.total - CELL_PAD * 2,
    });
  }
}

/* ---- summary ------------------------------------------------------ */

/** Tall enough for three lines of supplier notes plus the four term bullets. */
const SUMMARY_H = 190;

function drawSummary(page: Page, fonts: Fonts, c: Palette, data: OrderPdfData, top: number) {
  const totalsW = 224;
  const notesW = CONTENT_W - totalsW - 12;

  /* — totals card (left) — */
  const tl = MARGIN;
  box(page, { left: tl, top, w: totalsW, h: SUMMARY_H, radius: 14, fill: c.white });
  box(page, { left: tl, top, w: totalsW, h: SUMMARY_H, radius: 14, stroke: c.border, strokeWidth: 0.9 });

  const padded = tl + 16;
  const tr = tl + totalsW - 16;
  const rows: { label: string; value: string; tone?: Color }[] = [
    { label: "שורות בהזמנה", value: String(data.lines.length) },
    { label: "מוצרים מתומחרים", value: String(data.lines.length - data.totals.unpriced) },
  ];
  if (data.totals.unpriced > 0) {
    rows.push({ label: "ללא מחיר במחירון", value: String(data.totals.unpriced), tone: c.warning });
  }

  let y = top + 18;
  for (const row of rows) {
    text(page, row.label, tr, y, { size: 9, font: fonts.reg, color: row.tone ?? c.text2, maxWidth: 120 });
    text(page, row.value, padded, y, {
      size: 9.6,
      font: fonts.bold,
      color: row.tone ?? c.text,
      align: "left",
      maxWidth: 90,
    });
    y += 19;
  }

  const bandTop = top + SUMMARY_H - 16 - 52;
  hairline(page, padded, bandTop - 12, totalsW - 32, c.hair);
  box(page, { left: padded, top: bandTop, w: totalsW - 32, h: 52, radius: 12, fill: c.ink });
  text(page, "סה״כ ההזמנה", tr - 6, bandTop + 11, {
    size: 8.4,
    font: fonts.med,
    color: c.white,
    opacity: 0.62,
    tracking: 0.9,
  });
  text(page, data.totals.sum, tr - 6, bandTop + 25, {
    size: 19,
    font: fonts.bold,
    color: c.white,
    maxWidth: totalsW - 48,
  });

  /* — notes / terms panel (right) — */
  const nl = RIGHT - notesW;
  box(page, { left: nl, top, w: notesW, h: SUMMARY_H, radius: 14, fill: c.panel });
  const nr = RIGHT - 18;

  text(page, "הערות ותנאים", nr, top + 18, {
    size: 7.4,
    font: fonts.med,
    color: c.text3,
    tracking: 1.1,
  });

  let ny = top + 34;
  const inner = notesW - 36;

  if (data.supplier.notes) {
    for (const chunk of wrap(data.supplier.notes, { size: 9.2, font: fonts.reg }, inner, 3)) {
      text(page, chunk, nr, ny, { size: 9.2, font: fonts.reg, color: c.text });
      ny += 13.5;
    }
    ny += 6;
  }

  const bullets = [
    `סך הכמויות: ${data.totals.unitsLabel}`,
    `ימי אספקה מהספק: ${data.supplier.deliveryDays}`,
    data.supplier.phone ? `לבירורים: ${data.supplier.phone}` : "",
    "המחירים לפי מחירון הספק במערכת ואינם כוללים מע״מ, אלא אם סוכם אחרת.",
  ].filter(Boolean);

  for (const bullet of bullets) {
    for (const [i, chunk] of wrap(bullet, { size: 8.4, font: fonts.reg }, inner - 10, 2).entries()) {
      if (i === 0) {
        page.drawCircle({ x: nr - 3, y: PAGE_H - ny - 4.6, size: 1.5, color: c.text4 });
      }
      text(page, chunk, nr - 10, ny, { size: 8.4, font: fonts.reg, color: c.text2 });
      ny += 12;
    }
    ny += 2;
  }
}

/* ---- footer ------------------------------------------------------- */

function drawFooter(page: Page, fonts: Fonts, c: Palette, data: OrderPdfData, index: number, count: number) {
  const top = PAGE_H - 46;
  hairline(page, MARGIN, top, CONTENT_W, c.hair);
  text(page, `${data.businessName} · הופק ב־${data.generatedAt}`, RIGHT, top + 12, {
    size: 7.6,
    font: fonts.reg,
    color: c.text3,
    maxWidth: 340,
  });
  text(page, `עמוד ${index} מתוך ${count}`, MARGIN, top + 12, {
    size: 7.6,
    font: fonts.med,
    color: c.text3,
    align: "left",
  });
}

/* ------------------------------------------------------------------ */

/** ₪1,240.50 — decimals only when they carry information. */
export function formatShekel(n: number): string {
  const rounded = Math.round(n * 100) / 100;
  const body = Number.isInteger(rounded)
    ? rounded.toLocaleString("en-US")
    : rounded.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `₪${body}`;
}
